import { act, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener() {}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() { return { theme: "light" }; }
	},
	PostMessageTransport: class { close() {} },
}));

it("review probe observes the late-standard-capability save gap", async () => {
	const compatParent = Object.assign(new EventTarget(), {
		location: { origin: "https://chatgpt.com" },
	});
	Object.defineProperty(window, "parent", { configurable: true, value: compatParent });
	Object.defineProperty(window, "openai", {
		configurable: true,
		value: {
			widgetState: {
				privateContent: {
					lobuViewSnapshot: {
						version: 1,
						data: { title: "Cached result" },
					},
				},
			},
		},
	});
	bridge.callServerTool.mockImplementation(async ({ name }) => {
		if (name === "restore_lobu_app_result") {
			return {
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Cached result" },
					view_state: { "details.open": false },
				},
			};
		}
		if (name === "save_lobu_app_state") {
			return { isError: false, structuredContent: { saved: true } };
		}
		return { isError: false };
	});

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data, setViewState, viewState } = useMcpApp<{ title: string }>();
		return <><span>{data?.title}</span><span>open:{String(viewState["details.open"])}</span><button type="button" onClick={() => setViewState("details.open", true)}>Expand</button></>;
	}
	render(<Provider devMock={{ title: "Development" }}><Probe /></Provider>);
	expect(await screen.findByText("Cached result")).toBeInTheDocument();
	await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
	fireEvent.click(screen.getByRole("button", { name: "Expand" }));
	await act(() => new Promise((resolve) => window.setTimeout(resolve, 300)));
	expect(bridge.callServerTool).not.toHaveBeenCalled();

	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({
				structuredContent: {},
				_meta: { "lobu/mcp-app-snapshot-capability": "late-standard-token" },
			});
		}
	});
	expect(await screen.findByText("open:true")).toBeInTheDocument();
	await act(() => new Promise((resolve) => window.setTimeout(resolve, 300)));
	const saves = bridge.callServerTool.mock.calls.filter(([request]) => request.name === "save_lobu_app_state");
	expect(saves).toHaveLength(0);
});
